from pathlib import Path

from threetears.evals import Eval

from tally import tally_file

def figures(case):
    """Our hits and bytes for the day's page, from the day's access log."""
    stats = tally_file(Path("data/logs") / f"access-{case['day']}.log").pages.get(case["page"])
    return {"hits": stats.hits if stats else 0, "bytes": stats.bytes if stats else 0}


def matches_dashboard(case, out):
    """The hits and bytes are the add-on dashboard's."""
    return (out["hits"], out["bytes"]) == (case["hits"], case["bytes"])

dashboard = Eval("data/dashboard.jsonl", runner=figures, grader=[matches_dashboard], k=1)
